struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const Particle pi = in[i];
    const float G = 1.0f;
    const float softening = 0.001f;
    float ax = 0.0f;
    float ay = 0.0f;
    float az = 0.0f;

    for (int j = 0; j < n; ++j) {
        if (i == j) continue;

        const Particle pj = in[j];
        const float dx = pj.x - pi.x;
        const float dy = pj.y - pi.y;
        const float dz = pj.z - pi.z;
        const float distSq = dx * dx + dy * dy + dz * dz + softening;
        const float invDist = rsqrtf(distSq);
        const float scale = G * pj.mass * invDist * invDist * invDist;

        ax += scale * dx;
        ay += scale * dy;
        az += scale * dz;
    }

    Particle p = pi;
    p.vx += ax * dt;
    p.vy += ay * dt;
    p.vz += az * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;
    out[i] = p;
}

